with rollup_totals as (select dim.channel, dim.status as order_status, e.status as shipment_status, count(*) as cnt, min(e.cost) as min_cost from shipments e inner join orders dim on e.order_id = dim.id group by grouping sets ((dim.channel, dim.status, e.status), (dim.channel, dim.status), (dim.channel))) select order_status, cnt, min_cost, case when order_status rlike '^(COMPLETED|SHIPPED)$' then 'GROUP_B' when order_status rlike '^(PENDING|CANCELLED)$' then 'PRIORITY' else 'OTHER_ZONE' end as order_status_zone from rollup_totals order by cnt nulls first;
